  "19. Rakaman Laporan Progres": "19. Recording of Progress Reports",
  "19.1. Saya dengan ini mengesahkan persetujuan yang diberikan kepada Ibnu Sina Wellness berkenaan dengan fotografi, rakaman video, penggambaran, atau rakaman audio bagi tujuan penyimpanan rekod pesakit, informasi, pembelajaran atau promosi.": "19.1. I hereby confirm my consent given to Ibnu Sina Wellness regarding photography, video recording, filming, or audio recording for the purposes of patient record-keeping, information, education, or promotion.",
  "19.1. Saya dengan ini mengesahkan persetujuan yang diberikan kepada Ibnu Sina Wellness berkenaan dengan fotografi, rakaman video, penggambaran, atau rakaman audio bagi tujuan penyimpanan rekod pesakit, informasi, pembelajaran atau promosi.\\n\\n19.2. Saya sedia maklum bahawa maklumat yang diberikan kepada Ibnu Sina Wellness akan digunakan, diedarkan atau dikongsikan kepada mana-mana pihak ketiga berkenaan dengan fotografi, rakaman video, penggambaran, atau rakaman audio untuk siaran langsung atau pre-rakaman.": "19.1. I hereby confirm my consent given to Ibnu Sina Wellness regarding photography, video recording, filming, or audio recording for the purpose of keeping patient records, information, education, or promotion.\\n\\n19.2. I am aware that information given to Ibnu Sina Wellness will be used, distributed, or shared with any third party in relation to photography, video recording, filming, or audio recording for live broadcast or pre-recording.",
  "19.2. Saya sedia maklum bahawa maklumat yang diberikan kepada Ibnu Sina Wellness akan digunakan, diedarkan atau dikongsikan kepada mana-mana pihak ketiga berkenaan dengan fotografi, rakaman video, penggambaran, atau rakaman audio untuk siaran langsung atau pre-rakaman.": "19.2. I am aware that the information provided to Ibnu Sina Wellness will be used, distributed, or shared with any third party in relation to photography, video recording, filming, or audio recording for live broadcast or pre-recording.",
