  "22.1. Hari rawatan ialah pada hari Jumaat, Sabtu dan Ahad.": "22.1. Treatment days are Friday, Saturday, and Sunday.",
  "22.1. Hari rawatan ialah pada hari Jumaat, Sabtu dan Ahad.\\n\\n22.2. Saya faham bahawa jika rawatan di luar waktu dan hari yang dinyatakan, akan ada cas \"on-call\" RM50/sejam.\\n\\n22.3. Saya faham bahawa ISW berhak untuk menukar waktu dan hari rawatan atas apa-apa sebab dan tiada cas \"on-call\" akan dikenakan.": "22.1. Treatment days are on Friday, Saturday and Sunday.\\n\\n22.2. I understand that if treatment occurs outside the stated hours and days, an \"on-call\" charge of RM50/hour will apply.\\n\\n22.3. I understand that ISW reserves the right to change the treatment hours and days for any reason, and no \"on-call\" charge will be imposed in that case.",
  "22.2. Saya faham bahawa jika rawatan di luar waktu dan hari yang dinyatakan, akan ada cas \"on-call\" RM50/sejam.": "22.2. I understand that for treatment outside the stated hours and days, there will be an \"on-call\" charge of RM50/hour.",
  "22.3. Saya faham bahawa ISW berhak untuk menukar waktu dan hari rawatan atas apa-apa sebab dan tiada cas \"on-call\" akan dikenakan.": "22.3. I understand that ISW reserves the right to change the treatment hours and days for any reason and no \"on-call\" charge will be imposed.",
