  "Batu hempedu boleh melembut, mengembang, dan pecah sebelum dikeluarkan melalui proses pembuangan air besar. Jika anda mengalami kesakitan semasa proses ini, diharap bersabar kerana ia adalah sebahagian daripada reaksi pemulihan jasad. Jika kesakitan terlalu teruk, ambil ubat penahan sakit (painkiller) seperti yang disarankan. Jaga pemakanan dan pastikan anda mendapat rehat yang mencukupi.": "Gallstones may soften, expand, and break apart before being passed during bowel movements. If you experience pain during this process, please be patient as it is part of the body's recovery reaction. If the pain is too severe, take a painkiller as recommended. Watch your diet and make sure you get enough rest.",
