  "Ibnu Sina Wellness telah memaklumkan tentang reaksi pemulihan dan gejala prosedur, yang boleh termasuk, tetapi tidak terhad kepada: pening atau loya, sakit-sakit badan, flu, lebam, perubahan warna kulit, dan kemungkinan risiko lain yang tidak dijangka. Dalam sesetengah kes, simptom saya mungkin bertambah buat sementara waktu sebelum ia mula beransur baik. Saya akan menanggung segala risiko yang terlibat dengan prosedur saya.": "Ibnu Sina Wellness has informed me of the healing reactions and symptoms of the procedure, which may include, but are not limited to: dizziness or nausea, body aches, flu, bruising, skin discolouration, and other possible unexpected risks. In some cases, my symptoms may temporarily worsen before they begin to improve. I will bear all risks involved in my procedure.",
