  "Jika anda masukkan pautan video, fail video tidak perlu dimuat naik.": "If you enter a video link, the video file does not need to be uploaded.",
  "Jika anda mempunyai alahan terhadap makanan, minuman, atau bahan tertentu, sila maklumkan kepada Coach anda. Contoh: alahan terhadap air kelapa.": "If you are allergic to certain foods, drinks, or substances, please inform your Coach. For example: an allergy to coconut water.",
  "Jika anda mempunyai simptom seperti demam, batuk berkahak, dan selsema, sila dapatkan nasihat doktor di klinik terlebih dahulu untuk memastikan penyakit yang dialami bukanlah penyakit berjangkit dan sila maklumkan kepada kami.": "If you have symptoms such as fever, phlegmy cough, or a cold, please seek advice from a doctor at a clinic first to confirm that your illness is not contagious, and please inform us.",
  "Jika anda mengalami anemia, tahap hemoglobin (HB) yang terlalu rendah boleh memberi kesan serius kepada kesihatan. Secara umumnya, jika HB turun di bawah 7 g/dL, anda mungkin memerlukan pemindahan darah di hospital untuk mengelakkan komplikasi seperti keletihan melampau, sesak nafas, dan risiko kegagalan organ.": "If you have anaemia, an excessively low haemoglobin (HB) level can seriously affect your health. Generally, if your HB drops below 7 g/dL, you may need a blood transfusion at a hospital to avoid complications such as extreme fatigue, shortness of breath, and the risk of organ failure.",
  "Jika anda mengalami pitam, atau pengsan di rumah, sila dapatkan nasihat daripada Doktor di hospital dengan kadar segera. Sila maklumkan kepada Coach untuk tindakan seterusnya.": "If you experience dizziness or faint at home, please seek advice from a doctor at a hospital immediately. Please inform your Coach for the next steps.",
  "Jika anda mengalami simptom serius, jangan tunggu!": "If you experience serious symptoms, don't wait!",
  "Jika anda mengalami tanda-tanda keracunan seperti cirit-birit berterusan, kejang perut, lemah, serta tidak bermaya selama tiga hari berturut-turut, sila segera rujuk ke klinik.": "If you experience signs of poisoning such as persistent diarrhoea, stomach cramps, weakness, and lethargy for three consecutive days, please refer to a clinic immediately.",
  "Jika anda menghadapi masalah untuk menyertai, sila hubungi sokongan kami.": "If you have trouble joining, please contact our support.",
  "Jika anda merasa kurang makan semasa menjalani rawatan Overhaul Body™, itu adalah perkara biasa. Kurang selera makan juga mungkin berlaku.": "If you feel like eating less during Overhaul Body™ treatment, this is normal. A reduced appetite may also occur.",
  "Jika anda sedang mengambil ubat hospital, pastikan mengambil ubat tersebut satu jam sebelum atau selepas minum Herba Thoharah.": "If you are taking hospital medication, make sure to take it one hour before or after drinking Herba Thoharah.",
  "Jika anda tidak menemui jawapan yang anda cari, pasukan kami sedia membantu.": "If you can't find the answer you're looking for, our team is here to help.",
  "Jika berlaku kecemasan, sila segera pergi ke hospital untuk mendapatkan rawatan lanjut. (Rujuk buku Sains Di Sebalik Overhaul Body™ m/s 276)": "In an emergency, please go to a hospital immediately for further treatment. (Refer to the book The Science Behind Overhaul Body™ p. 276)",
  "Jika berlaku simptom serius, sila ikut langkah berikut:": "If serious symptoms occur, please follow these steps:",
  "Jika diisi, lawatan susulan baharu akan dicipta secara automatik bila lawatan ini ditandakan selesai.": "If filled in, a new follow-up visit will be created automatically when this visit is marked complete.",
  "Jika simptom menjadi semakin teruk atau berpanjangan, sila hubungi coach anda.": "If symptoms get worse or persist, please contact your coach.",
