  "Pastikan anda memahami semua langkah rawatan yang diajar. Jika terdapat sebarang kekeliruan, rujuk buku Sains Di Sebalik Overhaul Body™ atau bertanya kepada Coach dengan segera.": "Make sure you understand all the treatment steps taught. If there is any confusion, refer to the book The Science Behind Overhaul Body™ or ask your Coach immediately.",
  "Pastikan anda mengambil air kelapa (rujuk buku Sains Di Sebalik Overhaul Body™ m/s 189) (kecuali pesakit buah pinggang dan masalah paru-paru) dan yogurt setiap hari.": "Make sure you drink coconut water (refer to the book The Science Behind Overhaul Body™ p. 189) (except for kidney patients and those with lung problems) and yoghurt every day.",
  "Pastikan anda sudah mengalas perut sebelum datang untuk menjalani rawatan di Ibnu Sina Wellness™.": "Make sure you have eaten something before coming for treatment at Ibnu Sina Wellness™.",
  "Pastikan anda tidak tidur dalam bilik berhawa dingin sepanjang malam. Sebaiknya, gunakan kipas atau pastikan ada pengudaraan yang baik untuk tidur yang lebih nyaman dan menyihatkan.": "Make sure you do not sleep in an air-conditioned room all night. It is better to use a fan or ensure good ventilation for more comfortable and healthier sleep.",
  "Pastikan dokumen yang dimuat naik jelas dan berkaitan dengan rawatan anda untuk memudahkan rujukan oleh doktor.": "Make sure the uploaded documents are clear and relevant to your treatment for easy reference by the doctor.",
  "Pastikan getah pada botol madu masih ada": "Make sure the rubber seal on the honey bottle is still intact",
  "Pastikan guna format betul dengan tanda": "Make sure to use the correct format with the",
  "Pastikan kondisi kesihatan tepat & lengkap": "Ensure health conditions are accurate & complete",
  "Pastikan mesej ringkas dan mudah difahami.": "Keep the message short and easy to understand.",
  "Pastikan pesakit melengkapkan amalan harian untuk penilaian yang lebih tepat.": "Ensure patients complete their daily practices for a more accurate assessment.",
  "Pastikan pesakit telah makan sekurang-kurangnya 2 jam sebelum ujian.": "Make sure the patient has eaten at least 2 hours before the test.",
  "Pastikan pesakit tidak makan atau minum sekurang-kurangnya 30 minit sebelum ujian.": "Make sure the patient has not eaten or drunk anything for at least 30 minutes before the test.",
  "Pastikan semua maklumat adalah tepat sebelum membuat perubahan dan menyimpan.": "Make sure all details are correct before making changes and saving.",
  "Pastikan tajuk ringkas dan jelas": "Ensure the title is concise and clear",
