  "Salin": "Copy",
  "Salin (copy-paste) terus dari jadual Word/Excel — Solusi\n                  setiap reaksi, Saranan Diet & Nutrisi dan Gaya Hidup Fitrah untuk seluruh kategori. Sistem akan\n                  auto-cipta tindakan, tetapkan jenis (pemakanan/gaya hidup) dan petakan ke reaksi berkaitan.\n                  Tindakan yang sudah wujud (nama sama) diguna semula — selamat di-import berulang kali.": "Copy-paste directly from a Word/Excel table — the Solution for each reaction, Diet & Nutrition Recommendations and Fitrah Lifestyle for the whole category. The system will auto-create actions, set the type (nutrition/lifestyle) and map them to the related reactions. Actions that already exist (same name) are reused — safe to import repeatedly.",
