  "Saya telah diberi penerangan penuh pakej program Jumpstart / New Life Challenge / Overhaul Body, dengan jelas oleh Ibnu Sina Wellness.": "I have been given a full and clear explanation of the Jumpstart / New Life Challenge / Overhaul Body programme package by Ibnu Sina Wellness.",
  "Saya telah membaca dan bersetuju dengan": "I have read and agree to",
  "Saya tidak akan memaksa Ibnu Sina Wellness untuk bertanggungjawab ke atas sebarang kekurangan hasil program Jumpstart / New Life Challenge / Overhaul Body.": "I will not hold Ibnu Sina Wellness liable for any shortfall in the results of the Jumpstart / New Life Challenge / Overhaul Body programme.",
