  "Sekiranya anda menghadapi sesak nafas, sakit dada, rasa berdebar-debar, atau asma, sila maklumkan kepada pihak kami terlebih dahulu sebelum mengambil Herba Thoharah.": "If you experience shortness of breath, chest pain, palpitations, or asthma, please inform us first before taking Herba Thoharah.",
